#!/bin/bash
# CarMaa — کارت «تجربه‌ای متفاوت» صفحه اصلی (طراحی اختصاصی برای عکس ماشین قرمز)
# استفاده: داخل پوشه‌ی پروژه (جایی که index.html هست) اجرا کن:   bash carma-xp-card.sh
#   بدون بیلد مجدد داکر:  bash carma-xp-card.sh --no-deploy
# چندبار اجرا کردنش امنه (idempotent) و قبل از تغییر از فایل‌ها بکاپ می‌گیره.
set -e
DEPLOY=1; R="$PWD"
for a in "$@"; do case "$a" in --no-deploy) DEPLOY=0;; *) R="$a";; esac; done
[ -f "$R/index.html" ] || { [ -f "$R/carmaa/index.html" ] && R="$R/carmaa"; }
for f in index.html latest-rail.css js/35-home-dashboard.js; do
  [ -f "$R/$f" ] || { echo "❌ $f پیدا نشد — اسکریپت رو داخل پوشه‌ی پروژه اجرا کن"; exit 1; }
done
command -v python3 >/dev/null || { echo "❌ python3 نصب نیست"; exit 1; }

RC=0
set +e
python3 - "$R" <<'PY'
import os, re, sys, shutil, base64, time
R = sys.argv[1]
P = lambda *a: os.path.join(R, *a)
TS = time.strftime("%Y%m%d-%H%M%S")
TAG = "xp1"
IMG = "assets/home-experience-car.webp"

B64 = ""

CSS = r'''/* CM-XP:START — کارت «تجربه‌ای متفاوت» (ماشین قرمز) */
.cm-lt-promo.cm-xp{height:auto;aspect-ratio:736/412;background:#040203;border:1px solid rgba(255,64,52,.18);box-shadow:0 18px 40px -22px rgba(214,24,36,.55),inset 0 0 0 1px rgba(255,255,255,.025)}
.cm-xp .cm-lt-promo-img{object-position:center 60%;transform:scale(1.001);transition:transform 1.4s cubic-bezier(.2,.7,.2,1)}
.cm-xp .cm-lt-promo-img.is-flip{transform:none}
.cm-xp::after{background:linear-gradient(to bottom,rgba(0,0,0,.42) 0,rgba(0,0,0,0) 30%,rgba(0,0,0,0) 60%,rgba(0,0,0,.6) 100%)}
.cm-xp .cm-lt-promo-copy{position:absolute;inset:0;left:0;top:0;transform:none;width:auto;max-width:none;display:flex;flex-direction:column;align-items:center;justify-content:space-between;padding:clamp(12px,4.4vw,20px) 16px;text-align:center}
.cm-xp .cm-lt-promo-copy h3{margin:0;font-size:clamp(12.5px,3.7vw,15px);line-height:1.5;font-weight:700;letter-spacing:0;color:#fff;text-shadow:0 1px 14px rgba(0,0,0,.85)}
.cm-xp .cm-lt-promo-copy h3::before{content:"";display:block;width:22px;height:2px;margin:0 auto 7px;border-radius:2px;background:linear-gradient(90deg,#ff453a,#b3121d);box-shadow:0 0 10px rgba(255,48,48,.85)}
.cm-xp .cm-lt-cta{height:30px;padding:0 13px;gap:6px;font-size:12px;font-weight:700;color:#fff;background:linear-gradient(180deg,#e9232f,#a10f19);border:1px solid rgba(255,150,140,.38);box-shadow:0 8px 20px -8px rgba(233,35,47,.85),inset 0 1px 0 rgba(255,255,255,.22);transition:transform .18s ease,filter .18s ease,box-shadow .18s ease}
.cm-xp .cm-lt-cta svg{width:13px;height:13px}
.cm-xp .cm-lt-cta:active{transform:scale(.96)}
.cm-xp .cm-lt-cta:focus-visible{outline:2px solid #fff;outline-offset:2px}
@media (hover:hover){.cm-xp:hover .cm-lt-promo-img{transform:scale(1.035)}.cm-xp .cm-lt-cta:hover{filter:brightness(1.12);box-shadow:0 10px 24px -8px rgba(255,50,60,.95),inset 0 1px 0 rgba(255,255,255,.28)}}
@media (min-width:768px){
  .cm-lt-promo.cm-xp{aspect-ratio:auto;height:clamp(240px,22vw,300px)}
  .cm-xp .cm-lt-promo-img{object-position:center 56%}
  .cm-xp::after{background:linear-gradient(to left,rgba(0,0,0,.62) 0,rgba(0,0,0,.25) 30%,rgba(0,0,0,0) 52%)}
  .cm-xp .cm-lt-promo-copy{justify-content:center;align-items:flex-start;gap:16px;padding:0 clamp(32px,5vw,64px);text-align:start}
  .cm-xp .cm-lt-promo-copy h3{font-size:20px}
  .cm-xp .cm-lt-promo-copy h3::before{margin:0 0 9px;width:28px}
  .cm-xp .cm-lt-cta{height:34px;padding:0 16px;font-size:13px}
}
@media (prefers-reduced-motion:reduce){.cm-xp .cm-lt-promo-img,.cm-xp .cm-lt-cta{transition:none}.cm-xp:hover .cm-lt-promo-img{transform:none}}
/* CM-XP:END */'''

HTML = ('<section class="cm-lt-promo cm-xp" aria-label="تبلیغ">\n'
 '      <img class="cm-lt-promo-img" src="%s?v=%s" alt="" width="1472" height="824" loading="lazy" decoding="async" draggable="false" />\n'
 '      <div class="cm-lt-promo-copy"><h3>تجربه‌ای متفاوت در خرید خودرو</h3>'
 '<button type="button" class="cm-lt-cta" data-action="goListings" data-brand="all">شروع کنید '
 '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 12H5m0 0 6-6m-6 6 6 6"/></svg></button></div>\n'
 '    </section>') % (IMG, TAG)

def rd(f):
    with open(P(f), encoding="utf-8") as h: return h.read()
def wr(f, s):
    shutil.copy2(P(f), P(f) + ".bak-xp-" + TS)
    with open(P(f), "w", encoding="utf-8", newline="") as h: h.write(s)

# ---- بررسی همه‌چیز قبل از نوشتن (اگه خطا بود هیچ فایلی تغییر نمی‌کنه) ----
js = rd("js/35-home-dashboard.js")
pat = re.compile(r'<section class="cm-lt-promo[^"]*" aria-label="تبلیغ">.*?</section>', re.S)
if len(pat.findall(js)) != 1:
    sys.exit("❌ js/35-home-dashboard.js: بلوک کارت (cm-lt-promo) دقیقاً یک بار پیدا نشد — نسخه‌ی فایل با انتظار فرق داره؛ چیزی تغییر نکرد")
js2 = pat.sub(lambda m: HTML, js, count=1)

css = rd("latest-rail.css")
blk = re.compile(r'/\* CM-XP:START.*?CM-XP:END \*/', re.S)
css2 = blk.sub(lambda m: CSS, css) if blk.search(css) else css.rstrip("\n") + "\n\n" + CSS + "\n"

def bump(s):
    s = re.sub(r'(latest-rail\.css\?v=)[^"\'&\s]*', r'\g<1>' + TAG, s)
    def j(m):
        v = m.group(2)
        return m.group(1) + (v if re.search(r'(^|-)%s$' % TAG, v) else v + "-" + TAG)
    return re.sub(r'(35-home-dashboard\.js\?v=)([^"\'&\s]*)', j, s)

img = base64.b64decode(B64)
os.makedirs(P("assets"), exist_ok=True)
changed = []
if not os.path.isfile(P(IMG)) or open(P(IMG), "rb").read() != img:
    with open(P(IMG), "wb") as h: h.write(img)
    changed.append(IMG)
if js2 != js: wr("js/35-home-dashboard.js", js2); changed.append("js/35-home-dashboard.js")
if css2 != css: wr("latest-rail.css", css2); changed.append("latest-rail.css")
for f in ("index.html", "index_offline.html"):
    if os.path.isfile(P(f)):
        s = rd(f); s2 = bump(s)
        if s2 != s: wr(f, s2); changed.append(f)

print("✅ تغییر کرد: " + (", ".join(changed) if changed else "هیچ‌چیز (از قبل اعمال شده بود)"))
sys.exit(0 if changed else 3)
PY
RC=$?
set -e
[ $RC -eq 3 ] && { echo "ℹ️  از قبل اعمال شده."; exit 0; }
[ $RC -ne 0 ] && exit $RC

if [ "$DEPLOY" = "1" ] && [ -f "$R/docker-compose.prod.yml" ] && command -v docker >/dev/null && docker compose version >/dev/null 2>&1; then
  echo ">> بیلد مجدد سرویس وب (فایل‌های استاتیک داخل ایمیج هستن)..."
  cd "$R"
  ENVF=""; [ -f backend/.env ] && ENVF="--env-file backend/.env"
  docker compose -f docker-compose.prod.yml $ENVF up -d --build --no-deps web && echo "✅ سایت آپدیت شد." \
    || echo "⚠️ بیلد داکر خطا داد؛ فایل‌ها پچ شدن ولی دستی اجرا کن: bash deploy.sh"
else
  echo "ℹ️  بیلد داکر انجام نشد. اگه سایت از داخل داکر سرو می‌شه اجرا کن: bash deploy.sh  (یا بدون داکر: فقط کش مرورگر رو رفرش کن)"
fi
